            "AND stat_date >= #{startDate} AND stat_date <= #{endDate} " +
            "ORDER BY stat_date")
    List<StatRecord> selectByDateRange(@Param("userId") Long userId, 
                                      @Param("startDate") LocalDate startDate,
                                      @Param("endDate") LocalDate endDate);

    /**
     * 统计用户总学习时间
     */
