const BASE_URL = 'http://localhost:8080/api' // 后端API地址

// 请求拦截器
const request = (options = {}) => {
  return new Promise((resolve, reject) => {
    // 合并配置
    const config = {
      url: '',
      method: 'GET',
      data: {},
      header: {
        'Content-Type': 'application/json'
      },
      ...options
    }

    // 添加token到请求头
