                    })
                  }
                })
              } else {
                // 其他错误，显示错误信息
                uni.showToast({
                  title: errorMsg,
                  icon: 'none',
                  duration: 2000
                })
              }

              reject(new Error(errorMsg))
            }
          } else {
            // 响应格式错误
            uni.showToast({
              title: '响应格式错误',
              icon: 'none'
            })
            reject(new Error('响应格式错误'))
          }
        } else if (statusCode === 401) {
          // 未授权
          uni.removeStorageSync('token')
          uni.removeStorageSync('userInfo')

          uni.showModal({
            title: '提示',
            content: '请先登录',
            showCancel: false,
            success: () => {
              uni.redirectTo({
                url: '/pages/login/login'
              })
            }
          })
          reject(new Error('未授权'))
        } else if (statusCode === 403) {
          // 禁止访问
          uni.showToast({
            title: '权限不足',
            icon: 'none'
          })
          reject(new Error('权限不足'))
        } else if (statusCode === 404) {
          // 资源不存在
          uni.showToast({
            title: '资源不存在',
            icon: 'none'
          })
          reject(new Error('资源不存在'))
        } else if (statusCode >= 500) {
          // 服务器错误
          uni.showToast({
            title: '服务器错误',
            icon: 'none'
          })
          reject(new Error('服务器错误'))
        } else {
          // 其他HTTP错误
          uni.showToast({
            title: `请求失败: ${statusCode}`,
            icon: 'none'
          })
          reject(new Error(`请求失败: ${statusCode}`))
        }
      },
      fail: (err) => {
        // 隐藏加载中
        if (config.showLoading !== false) {
          uni.hideLoading()
        }

        // 网络错误
        uni.showToast({
          title: '网络连接失败',
          icon: 'none'
        })
        reject(err)
      },
      complete: () => {
        // 请求完成，可以在这里做一些清理工作
      }
    })
  })
}

// GET请求
request.get = (url, data = {}, options = {}) => {
  return request({
    url,
    method: 'GET',
    data,
    ...options
  })
}

// POST请求
request.post = (url, data = {}, options = {}) => {
  return request({
    url,
    method: 'POST',
    data,
    ...options
  })
}

// PUT请求
request.put = (url, data = {}, options = {}) => {
  return request({
    url,
    method: 'PUT',
    data,
    ...options
  })
}

